public int findDuplicate(int[] nums) {
        // 阶段一：先移动再比较，在环内相遇
        int fast = 0, slow = 0;
        do {
            fast = nums[nums[fast]];
            slow = nums[slow];
        } while (fast != slow);
        // 阶段二：慢指针回起点，两者同速前进，交点即环入口
        slow = 0;
        while (fast != slow) {
            fast = nums[fast];
            slow = nums[slow];
        }
        return fast;
    }

